const TANTIA_INFO={id:"tantia-bhil",title:"Tantia Bhil",quickStats:[{label:"Born",value:"1842, Badwani region",icon:"📍"},{label:"Died",value:"1889 (executed)",icon:"🕊️"},{label:"Community",value:"Bhil Tribal Community",icon:"🌿"},{label:"Known As",value:'"Indian Robin Hood"',icon:"🏹"},{label:"Region",value:"Malwa–Nimar (Central India)",icon:"🗺️"},{label:"Resistance Span",value:"~20 Years",icon:"⏳"}]},HISTORY_TEXT={title:"The Bandit Who Became a Folk Hero",paragraphs:["Tantia Bhil (also known as Tantya Bhil) was born around 1842 in the Bhil tribal belt of Central India, in the Nimar/Malwa region spanning parts of present-day Madhya Pradesh. He belonged to the Bhil community, one of India's largest tribal groups, concentrated in central and western India.","Facing exploitation from British colonial administration, moneylenders, and local landlords, Tantia Bhil turned to organized resistance, leading raids against oppressive landlords and colonial revenue collectors, and reportedly redistributing wealth to poorer tribal and rural communities — earning him comparisons to Robin Hood in popular memory.","For roughly two decades, he evaded capture by British colonial forces across the forests and hills of Central India, becoming a symbol of tribal defiance against colonial authority and exploitative local power structures.","Tantia Bhil was eventually captured and executed by British authorities in 1889. He remains a deeply respected folk hero among Bhil and other tribal communities in Central India, remembered through oral tradition, folklore, and regional cultural memory."]},TIMELINE_EVENTS=[{era:"c. 1842",title:"Born in the Nimar Region",description:"Tantia Bhil was born into the Bhil tribal community in Central India's Nimar/Malwa belt."},{era:"1860s–70s",title:"Early Resistance Begins",description:"Began organizing resistance against exploitative landlords, moneylenders, and colonial revenue policies affecting tribal communities."},{era:"1870s–80s",title:"Two Decades of Evasion",description:"Led a sustained campaign of raids and resistance across Central India's forests, evading capture by British colonial forces for years."},{era:"1889",title:"Capture and Execution",description:"Tantia Bhil was captured by British authorities and executed, ending his two-decade resistance."},{era:"Post-1889",title:"Folk Hero Status",description:"Became remembered in regional oral tradition and folklore as a symbol of tribal resistance and defiance against colonial and feudal exploitation."}],RESISTANCE_POINTS=[{title:"Resistance to Colonial Revenue Policy",description:"Opposed exploitative British revenue collection and land policies that disproportionately burdened tribal communities."},{title:"Raids Against Landlords",description:"Targeted oppressive landlords and moneylenders who exploited tribal populations in Central India."},{title:"Redistribution to the Poor",description:"Popular folklore credits him with redistributing seized wealth among poorer tribal and rural communities."},{title:"Guerrilla Tactics in Forest Terrain",description:"Used deep knowledge of the region's forests and hills to evade capture by colonial forces for roughly two decades."}],LEGACY_TEXT={paragraphs:["Tantia Bhil's legacy endures strongly within Bhil and other tribal communities of Central India, where he is remembered as a symbol of resistance against both colonial rule and local exploitation. His story has been passed down largely through oral tradition and regional folklore rather than formal historical records, reflecting the broader challenge of documenting tribal resistance movements from this period.","In recent decades, there has been growing academic and cultural interest in recovering and honoring the histories of tribal freedom fighters like Tantia Bhil, recognizing their contribution to India's broader anti-colonial resistance alongside more widely documented figures."]},GALLERY_QUERIES=["Bhil tribal community Madhya Pradesh","Nimar region Central India forest","tribal folk art Central India"],REFERENCES=[{text:"Government of Madhya Pradesh — regional tribal heritage documentation.",link:"#"},{text:"Guha, R. — 'Elementary Aspects of Peasant Insurgency in Colonial India' (context on tribal resistance).",link:"#"},{text:"Regional oral history and folklore archives on Bhil resistance leaders.",link:"#"},{text:"Anthropological Survey of India — studies on Bhil community history.",link:"#"}];